// For flash slots 1..4: the program data is read from the BB15 flash, so
// the program array is not linked into the sketch.
inline Model voiceLearn() {
  Model m;
  m.name = "voice_learn";
  m.info = voice_learn_data::info;
  m.infoSize = 520;
  m.blobSize = 2324;
  m.dataSize = 1804;
  m.dataCrc32 = 0x9156BA89;
  m.infoCrc32 = 0x1C8F353E;
  m.inputHeight = 1;
  m.inputWidth = 1;
  m.inputChannels = 304;
  m.outputCount = 20;
  m.labels = voice_learn_data::labels;
  m.labelCount = 2;
  return m;
}

// Complete program: needed for slot 0 (SPI push) and by the model flasher.
inline Model voiceLearnWithProgram() {
  Model m = voiceLearn();
  m.blob = voice_learn_data::program;
  return m;
}

